package local.tv.launcher;
import org.junit.Test;
import static org.junit.Assert.*;
public class NetworkPolicyTest {
 @Test public void strictHttpsOrigins(){assertTrue(NetworkPolicy.allowedUrl("https://api.themoviedb.org/3/movie/1"));for(String u:new String[]{"http://api.themoviedb.org/3","https://api.themoviedb.org.evil.test/","https://user@api.themoviedb.org/","https://api.themoviedb.org:444/","https://127.0.0.1/","https://api.themoviedb.org/#secret","file:///tmp/a"})assertFalse(u,NetworkPolicy.allowedUrl(u));}
 @Test public void imagePathsCannotTargetApiOrEscape(){assertTrue(NetworkPolicy.imageUrl("https://image.tmdb.org/t/p/w1280/abc_123.jpg"));for(String u:new String[]{"https://api.themoviedb.org/t/p/w1280/a.jpg","https://image.tmdb.org/t/p/w1280/../a.jpg","https://image.tmdb.org/t/p/w1280/a.jpg?token=value","https://image.tmdb.org/t/p/w1280/%2e%2e.jpg"})assertFalse(u,NetworkPolicy.imageUrl(u));}
 @Test public void boundsAndMediaTypes(){assertTrue(NetworkPolicy.validType("tv"));assertTrue(NetworkPolicy.validType("movie"));assertFalse(NetworkPolicy.validType("person"));assertFalse(NetworkPolicy.validId(0));assertFalse(NetworkPolicy.validId(-1));assertEquals("",NetworkPolicy.query(null));assertEquals("ab",NetworkPolicy.query("a\nb"));assertEquals(120,NetworkPolicy.query(new String(new char[150]).replace('\0','x')).length());}
 @Test public void credentialsStayUnadornedAndRejectInjection(){assertEquals("test.token",NetworkPolicy.credential(" Bearer test.token "));assertEquals("",NetworkPolicy.credential(""));assertFalse(NetworkPolicy.apiKey("test.token"));assertTrue(NetworkPolicy.apiKey(new String(new char[32]).replace('\0','a')));try{NetworkPolicy.credential("value\r\nInjected: yes");fail();}catch(IllegalArgumentException e){assertEquals("Invalid credential format",e.getMessage());}}
 @Test public void regionAndProviderLinksAreBounded(){assertEquals("IN",NetworkPolicy.region("IN"));try{NetworkPolicy.region("india");fail();}catch(IllegalArgumentException expected){}assertTrue(NetworkPolicy.providerLink("https://www.themoviedb.org/movie/693134/watch?locale=IN"));assertFalse(NetworkPolicy.providerLink("https://www.themoviedb.org.evil.test/movie/1/watch"));assertFalse(NetworkPolicy.providerLink("https://user@www.themoviedb.org/movie/1/watch"));}
 @Test public void genresUseExactNamesAndExplicitSciFiAlias(){assertTrue(NetworkPolicy.genreMatches("sci-fi","Science Fiction"));assertTrue(NetworkPolicy.genreMatches("sci fi","Sci-Fi & Fantasy"));assertTrue(NetworkPolicy.genreMatches("action","Action"));assertFalse(NetworkPolicy.genreMatches("act","Action"));assertFalse(NetworkPolicy.genreMatches("",""));}
}
